using System.Windows;
using System.Windows.Controls;
using Tune.Generic.DialogGenerics;
using Tune.Helpers;
using Tune.Helpers.DialogExtentions;
using Tune.Models.Playlist;
using Tune.Persistence.PlaylistStorage;
using Tune.Values.Static;

// Initially generated by AI, but edited. 
namespace Tune.Components.UI
{
    public partial class SelectPlaylist : DialogBaseStringPlaylistBase
    {
        // ==== Internal Properties ====
        public PlaylistBase? SelectedPlaylist { get; private set; }

        private PlaylistService? _service;

        // ==== Implement Interfaces ====
        public override PlaylistBase? Result
        {
            get => SelectedPlaylist;
            set => SelectedPlaylist = value;
        }

        // ==== Events ====
        public event EventHandler<PlaylistBase>? PlaylistSelected;

        // ==== Constructor ====
        public SelectPlaylist()
        {
            InitializeComponent();
            // MUST definite the size of the dialog
            this.Height = 400;
            this.Width = 700;

            // Process the arguments
            if (!String.IsNullOrEmpty(Argument))
                this.DescriptionTextBlock.Text = Argument;

            // Register events
            ConfirmButton.Click += OnConfirmClick;
            CancelButton.Click += OnCancelClick;
            PlaylistListBox.SelectionChanged += OnPlaylistListBoxSelectionChanged;

            _service = LoadableServicesHelper.GetPlaylistService();
            if (_service == null)
            {
                // TODO SHOW_TOAST
                MessageBox.Show("Not loaded service or service not exists.", Strings.APPLICATION_NAME, MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            SetPlaylists(_service.GetAllPlaylists());
            CreateButton.Click += OnCreateClick;
            ConfirmButton.IsEnabled = false;
        }

        // ==== UI Logic ====
        public void SetPlaylists(IEnumerable<PlaylistBase> playlists)
        {
            if (playlists == null)
            {
                PlaylistListBox.ItemsSource = null;
                SelectedPlaylist = null;
                ConfirmButton.IsEnabled = false;
                return;
            }

            var items = playlists
                .Where(p => p != null)
                .Select(p => new PlaylistDisplayItem(p))
                .ToList();
            PlaylistListBox.ItemsSource = items;
            PlaylistListBox.SelectedItem = null;
        }

        private void OnPlaylistListBoxSelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (PlaylistListBox.SelectedItem is PlaylistDisplayItem item)
            {
                SelectedPlaylist = item.Playlist;
                ConfirmButton.IsEnabled = true;
                PlaylistSelected?.Invoke(this, SelectedPlaylist);
            }
            else
            {
                SelectedPlaylist = null;
                ConfirmButton.IsEnabled = false;
            }
        }

        private void OnConfirmClick(object sender, RoutedEventArgs e)
        {
            if (SelectedPlaylist != null)
                RaiseConfirm();   // We must Raise UI events when ready to disappear
                                  // Similiar to base.xxx(); in Java
        }

        private void OnCancelClick(object sender, RoutedEventArgs e)
        {
            SelectedPlaylist = null;
            RaiseCancel();
        }

        private void OnCreateClick(object sender, RoutedEventArgs e)
        {
            var creator = new CreatePlaylist();
            var newPlaylist = creator.ShowCreatePlaylistDialog("请填写新歌单信息");
            if (newPlaylist != null && _service != null)
            {
                SetPlaylists(_service.GetAllPlaylists());
            }
        }


        private sealed class PlaylistDisplayItem
        {
            public PlaylistBase Playlist { get; }
            public PlaylistDisplayItem(PlaylistBase playlist) => Playlist = playlist;
            public override string ToString() => Playlist.Name;
        }
    }
}